"use client";

import * as React from "react";
import {
  AnimatePresence,
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
  type Transition,
  type Variants,
} from "framer-motion";
import { Check, Minus } from "lucide-react";
import { cn } from "@/lib/utils";

export type PricingTheme = "ivory" | "slate" | "midnight" | "ember" | "custom";
export type PricingLayout = "responsive" | "desktop" | "mobile";
export type PricingTransitionSpeed = "slow" | "medium" | "fast";

export type PricingPlan = {
  id: string;
  label: string;
  subtitle?: string;
  price: number;
  period?: string;
  badge?: string;
  ctaLabel?: string;
  ctaHref?: string;
  includedFeatureCount: number;
};

export type RadioPlanPricingProps = {
  plans?: PricingPlan[];
  features?: string[];
  featuresTitle?: string;
  featuresSubtitle?: string;
  plansTitle?: string;
  plansSubtitle?: string;
  currency?: string;
  defaultSelectedPlan?: string;
  layout?: PricingLayout;
  /**
   * `ivory` (default) follows the page: light, or dark under a `.dark` ancestor.
   * `slate` is always light, `midnight` always dark, `ember` dark with an orange accent,
   * and `custom` starts from `ivory` and takes the colour props below.
   */
  theme?: PricingTheme;
  backgroundColor?: string;
  cardBackgroundColor?: string;
  primaryTextColor?: string;
  secondaryTextColor?: string;
  accentColor?: string;
  ctaTextColor?: string;
  outerRadius?: number;
  optionRadius?: number;
  padding?: number;
  shadowIntensity?: number;
  showBorder?: boolean;
  transitionSpeed?: PricingTransitionSpeed;
  priceAnimationDuration?: number;
  headingFontFamily?: string;
  priceFontFamily?: string;
  bodyFontFamily?: string;
  showCTA?: boolean;
  showPlanBadges?: boolean;
  className?: string;
};

type Palette = {
  page: string;
  background: string;
  card: string;
  selected: string;
  primary: string;
  secondary: string;
  accent: string;
  ctaText: string;
  border: string;
};

/** Fixed palettes. `ivory` is not here: it is the adaptive light/dark palette set with classes below. */
const FIXED_PALETTES: Record<"slate" | "midnight" | "ember", Palette> = {
  slate: {
    page: "#f5f5f7",
    background: "#ffffff",
    card: "#f5f5f7",
    selected: "#ffffff",
    primary: "#1d1d1f",
    secondary: "#6e6e73",
    accent: "#0071e3",
    ctaText: "#ffffff",
    border: "rgba(0,0,0,0.08)",
  },
  midnight: {
    page: "#000000",
