    card: "#2c2c2e",
    selected: "#2c2c2e",
    primary: "#f5f5f7",
    secondary: "#a1a1a6",
    accent: "#0071e3",
    ctaText: "#ffffff",
    border: "rgba(255,255,255,0.1)",
  },
  ember: {
    page: "#000000",
    background: "#1c1c1e",
